import { describe, expect, it } from "vitest";
import fixtures from "./__fixtures__/layout.json";
import { layoutText, parseMetrics, type FontMetricsJson } from "./textLayout";

// Generated by backend/scripts/gen_layout_fixtures.py from the Python implementation (the source of truth).
const fonts = Object.fromEntries(Object.entries(fixtures.fonts).map(([k, v]) => [k, parseMetrics(v as FontMetricsJson)]));
const close = (a: number, b: number) => expect(a).toBeCloseTo(b, 6);

describe("layoutText matches the Python renderer", () => {
  for (const c of fixtures.cases) {
    it(c.name, () => {
      const p = c.params;
      const got = layoutText(
        c.text,
        {
          boxX: p.box_x,
          boxY: p.box_y,
          boxW: p.box_w,
          boxH: p.box_h,
          sizePx: p.size_px,
          minSizePx: p.min_size_px,
          stepPx: p.step_px,
          letterSpacingPx: p.letter_spacing_px,
          lineHeight: p.line_height,
          wrap: p.wrap,
          autoShrink: p.auto_shrink,
          align: p.align as "left" | "center" | "right",
          valign: p.valign as "top" | "middle" | "bottom",
        },
        fonts[c.font],
        "fallback" in c && c.fallback ? fonts[c.fallback] : null,
      );
      const exp = c.expected;
      close(got.sizePx, exp.size_px);
      close(got.lineHeightPx, exp.line_height_px);
      expect(got.overflow).toBe(exp.overflow);
      expect(got.missing).toEqual(exp.missing);
      expect(got.lines.map((l) => l.text)).toEqual(exp.lines.map((l) => l.text));
      got.lines.forEach((line, i) => {
        const e = exp.lines[i];
        close(line.width, e.width);
        close(line.x, e.x);
        close(line.baseline, e.baseline);
        expect(line.glyphs.length).toBe(e.glyphs.length);
        line.glyphs.forEach((g, j) => {
          expect(g.char).toBe(e.glyphs[j].char);
          expect(g.font).toBe(e.glyphs[j].font);
          close(g.x, e.glyphs[j].x);
        });
      });
    });
  }
});
